html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Known job artwork — individual review register</title><style>body{margin:0;background:#edf4fa;color:#25304a;font:17px/1.5 system-ui}main{max-width:1380px;margin:auto;padding:24px}h1,h2,h3{line-height:1.25}a{color:#504096}header,.controls,article{background:white;padding:20px;border-radius:16px;margin-bottom:16px}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}input,select,button{font:inherit;padding:10px;border:1px solid #9cabbd;border-radius:8px}input{min-width:260px;flex:1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px}article{margin:0;min-width:0}figure{margin:0;background:repeating-conic-gradient(#dce5ed 0% 25%,#f8fbff 0% 50%) 50%/24px 24px;border-radius:10px}img{display:block;width:100%;height:220px;object-fit:contain}code{overflow-wrap:anywhere;font-size:13px}small{display:block;color:#505a6c}.score{font-weight:700}.priority{color:#90451c}.pending{color:#755618}nav{display:flex;gap:16px;align-items:center;justify-content:center;margin:22px}details{margin:12px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.cards>*,.grid>*{min-width:0}article,.card{min-width:0}h2,h3,code,a{overflow-wrap:anywhere}img{max-width:100%}</style><main><header><a href="index.html">Current review entry</a><h1>Known job artwork: individual review register</h1><p id="summary">Loading exact register…</p><p>This combines the Day One and Day Two discovery lists and individual pose cells. Each earlier opinion retains its date and source boundary. Some shared dependencies may lie outside jobs; current binding, visible composition and complete actions still need review.</p><p><a href="ALL_ITEMS.json">Download the complete written register and hashes</a> · <a href="../day_two_boxing_live_refinement_v1_20261001/index.html">Current boxing artwork and sequences</a> · <a href="../day_one_pool_live_refinement_v2_20261001/index.html">Current pool props and sequences</a></p></header><div class="controls"><label for="search">Find an item</label><input id="search" type="search" placeholder="Name, ID, source path or evaluation"><label for="filter">Review lane</label><select id="filter"><option value="priority">Current source priorities ≤4.5</option><option value="unreviewed">Current source review required</option><option value="all">All known items</option><option value="cells">Individual pose cells</option><option value="observed">Recorded Day One references</option><option value="changed">Changed source bytes</option></select><label for="order">Sort</label><select id="order"><option value="weak">Lowest current score first</option><option value="id">Item ID</option></select></div><p id="result" aria-live="polite"></p><nav><button id="previous">Previous</button><span id="page"></span><button id="next">Next</button></nav><div id="items" class="grid"></div><nav><button id="previous-bottom">Previous</button><span id="page-bottom"></span><button id="next-bottom">Next</button></nav><p>Scores are first-pass drafting evaluations. A source score does not grant mounted, action, device, child or owner acceptance. Originals, rejected attempts and earlier reports remain available.</p><script>
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let registry,filtered=[],page=0;const size=30;const url=p=>'../../'+p;
function render(){let end=Math.min(filtered.length,(page+1)*size),start=page*size;document.querySelector('#result').textContent=`${filtered.length} matching items · showing ${filtered.length?start+1:0}–${end}`;for(const id of ['page','page-bottom'])document.getElementById(id).textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(filtered.length/size))}`;for(const id of ['previous','previous-bottom'])document.getElementById(id).disabled=page===0;for(const id of ['next','next-bottom'])document.getElementById(id).disabled=end>=filtered.length;document.querySelector('#items').innerHTML=filtered.slice(start,end).map(q=>`<article id="${esc(q.id)}"><h2>${esc(q.id)}</h2><small>${esc(q.kind)} · ${esc(q.families.join(' / '))}</small><figure><img loading="lazy" src="${esc(url(q.image_path))}" alt="${esc(q.id+' '+q.path)}"></figure><small>${esc(q.image_scope)}</small><p><code>${esc(q.path)}</code>${q.region?'<small>Individual atlas region: '+esc(q.region.join(', '))+'</small>':''}</p><p class="score ${q.priority?'priority':'pending'}">Current source: ${q.current_source_score===null?'review required':esc(q.current_source_score)+'/5'}${q.priority?' · priority':''}</p><p>${esc(q.evaluation)}</p>${q.refinement?'<p><strong>Refinement:</strong> '+esc(q.refinement)+'</p>':''}<small>${esc(q.current_byte_status)} · Earlier source opinion: ${q.historical_source_score===null?'unassigned':esc(q.historical_source_score)+'/5'} · Mounted/action scores unassigned in this register.</small>${q.protected_original?'<small>Protected original preserved.</small>':''}${q.latest_refinement?'<p><a href="'+esc(url(q.latest_refinement.report))+'">Later individual refinement</a><br>'+esc(q.latest_refinement.note)+'</p>':''}<details><summary>Identity, hashes and reference evidence</summary><pre>${esc(JSON.stringify({aliases:q.aliases,earlier_sha256:q.earlier_sha256,current_checkout_sha256:q.current_checkout_sha256,source_qualification:q.source_qualification,native_reference_observations:q.native_reference_observations},null,2))}</pre></details><p>${[...new Set(q.original_reports)].map((p,i)=>'<a href="'+esc(url(p))+'">Earlier report '+(i+1)+'</a>').join(' · ')}</p></article>`).join('')}
function apply(){const query=document.querySelector('#search').value.toLowerCase(),lane=document.querySelector('#filter').value;filtered=registry.items.filter(q=>(!query||JSON.stringify(q).toLowerCase().includes(query))&&(lane==='all'||lane==='priority'&&q.priority||lane==='unreviewed'&&q.current_source_score===null||lane==='cells'&&q.kind==='pose cell'||lane==='observed'&&q.native_reference_observations.length>0||lane==='changed'&&q.current_byte_status==='CHANGED_BYTES_REVIEW_REQUIRED'));filtered.sort(document.querySelector('#order').value==='id'?(a,b)=>a.id.localeCompare(b.id):(a,b)=>(a.current_source_score??99)-(b.current_source_score??99)||a.id.localeCompare(b.id));page=0;render()}
for(const id of ['search','filter','order'])document.getElementById(id).addEventListener(id==='search'?'input':'change',apply);for(const id of ['previous','previous-bottom'])document.getElementById(id).onclick=()=>{if(page>0){page--;render()}};for(const id of ['next','next-bottom'])document.getElementById(id).onclick=()=>{if((page+1)*size<filtered.length){page++;render()}};
fetch('ALL_ITEMS.json').then(x=>{if(!x.ok)throw Error(x.status);return x.json()}).then(d=>{registry=d;const c=d.counts;document.querySelector('#summary').textContent=`${c.unique_source_files} unique source files + ${c.individual_pose_cells} pose cells = ${c.registered_items} individually addressable entries. ${c.inclusive_current_source_priorities} current source priorities; ${c.unreviewed_current_source} current source reviews required. Updated ${d.created_utc}.`;apply()}).catch(e=>document.querySelector('#summary').textContent='Register unavailable: '+e.message);
</script></main></html>'''
html=html.replace('${c.unique_source_files} unique source files + ${c.individual_pose_cells} pose cells = ${c.registered_items}', '${c.unique_source_files} unique source files + ${c.individual_pose_cells} pose cells + ${c.additional_runtime_prop_regions} prop regions = ${c.registered_items}')
