html=html.replace('let registry,filtered=[],page=0;', "const regionStyle=q=>{const s=220/Math.max(q.region[2],q.region[3]),d=q.source_dimensions;return 'position:absolute;max-width:none;max-height:none;width:'+(d[0]*s)+'px;height:'+(d[1]*s)+'px;left:'+(-q.region[0]*s)+'px;top:'+(-q.region[1]*s)+'px;object-fit:fill'};let registry,filtered=[],page=0;")
html=html.replace('src="${esc(url(q.image_path))}" alt=', 'src="${esc(url(q.image_path))}" ${q.kind===\'runtime prop region\'&&q.image_path===q.path?\'style="\'+regionStyle(q)+\'"\':\'\'} alt=')
html=html.replace('<figure><img loading=', '<figure ${q.kind===\'runtime prop region\'&&q.image_path===q.path?\'style="height:\'+(220*q.region[3]/Math.max(q.region[2],q.region[3]))+\'px;width:\'+(220*q.region[2]/Math.max(q.region[2],q.region[3]))+\'px;position:relative;overflow:hidden;margin:auto"\':\'\'}><img loading=')
html=html.replace('${c.additional_runtime_prop_regions} prop regions = ${c.registered_items}', '${c.additional_runtime_prop_regions} runtime prop regions + ${c.individual_source_object_regions} source object regions = ${c.registered_items}')
